// Reading the owner's details and the agreement's terms from the text of a management agreement.
// Runs where the file is opened (the manager's browser now, the API later) with fixed rules — the
// document is never sent to an outside service to be read. Everything found is a suggestion that
// the manager checks before it is saved. Pure functions; the Python port in apps/api/core uses the
// same rules, and agreements generated by the system (template ft2) always read back exactly.
//
// Works best with labeled lines ("Name: …", "ת.ז.: …") under a heading that names the party
// ("## The owner", "## הבעלים"); free-text agreements ("between … and Moshe Levi, ID 123…") are
// read with patterns and are more likely to need corrections.
import type { FeeModel, Language, PartyKind } from "@/domain/types";
import { EMAIL, ID_NUMBER, isValidIsraeliId, LABELED, labelKind, normalizeLabel, PHONE_IL, SEGMENT_SEPARATOR } from "@/security/sensitive";

/** A value found in the document, with the line it came from so the manager can check it. */
export type Found<T = string> = { value: T; line: string; how: "label" | "pattern" };

export type ExtractWarning = "invalid_tax_id" | "no_name" | "no_contact" | "no_start" | "multiple_owners" | "end_before_start";

export type AgreementExtract = {
  language: Language;
  customer: {
    kind: Found<PartyKind>;
    name?: Found;
    taxId?: Found;
    phone?: Found; // E.164
    email?: Found;
    billingAddress?: Found;
  };
  terms: {
    startDate?: Found; // ISO date
    endDate?: Found;
    feeModel?: Found<FeeModel>;
    feePercent?: Found<number>;
    feeMinor?: Found<number>; // the fixed monthly fee, or the monthly minimum
    plusVat?: Found<boolean>;
    billingFrequency?: Found<"monthly" | "quarterly">;
    approvalThresholdMinor?: Found<number>;
  };
  properties: Found[]; // property addresses as written in the document
  warnings: ExtractWarning[];
};

/** Values of the management company itself, which appear in every agreement and are not the owner's. */
export type OwnValues = { name: string; phone: string; email: string };

type Role = "owner" | "company" | "property" | "other";

/** What a section is about, from its heading. */
function sectionRole(heading: string): Role {
  const h = normalizeLabel(heading);
  if (/בעלים|בעל הנכס|בעלי הנכס|המשכיר|הלקוח|owner|landlord|client/.test(h)) return "owner";
  if (/נכס|property|properties|premises/.test(h)) return "property";
  if (/החברה|המנהל|company|manager/.test(h)) return "company";
  return "other";
}

type Line = { text: string; role: Role; block?: number }; // block: the index of the "between … and …" party block

// Parties written as blocks, as Israeli agreements usually are:
//   בין / Between
//   <name>, ת.ז. <id> / <address> / טל: <phone>
//   (להלן: "המזמין") מצד שני          ← the designation says whose block it is
const PARTY_START = /^(?:בין|לבין|ובין|between|and)\s*:?$/i;
const DESIGNATION = /\(\s*(?:להלן|hereinafter)[^"“”״']*["“”״']([^"“”״']+)["“”״']/i;
const ADDRESS_START = /^(?:מרחוב|מרח['׳]|רחוב|of|residing at|address)\s+/i;

function designationRole(name: string): Role {
  const n = normalizeLabel(name);
  if (/מזמין|בעלים|בעל הנכס|בעלי הנכס|משכיר|לקוח|owner|landlord|client|principal/.test(n)) return "owner";
  if (/חבר|מנהל|company|manager/.test(n)) return "company";
  return "other";
}

/** The role of each line inside a party block, by the block's designation. */
function partyBlocks(raw: string[]): Map<number, { role: Role; block: number }> {
  const roles = new Map<number, { role: Role; block: number }>();
  for (let i = 0; i < raw.length; i++) {
    if (!PARTY_START.test(raw[i].trim())) continue;
    for (let j = i + 1; j < Math.min(raw.length, i + 12); j++) {
      if (PARTY_START.test(raw[j].trim())) break;
      const d = DESIGNATION.exec(raw[j]);
      if (d) {
        const role = designationRole(d[1]);
        for (let k = i + 1; k <= j; k++) roles.set(k, { role, block: i });
        break;
      }
    }
  }
  return roles;
}

/**
 * A heading without "##" (Word documents, pasted text): a short line ending with ":" that is not a
 * label, or a short line that names a party or the properties ("The owner", "הנכסים המנוהלים").
 * The document's title ("Management agreement") is not a section.
 */
function plainHeading(line: string): string | undefined {
  if (line.length > 50 || BULLET.test(line) || /הסכם|חוזה|agreement|contract/i.test(line)) return undefined;
  if (/[:：]$/.test(line)) return labelKind(line.slice(0, -1)) ? undefined : line.slice(0, -1);
  return !/[:：]/.test(line) && line.length <= 40 && sectionRole(line) !== "other" ? line : undefined;
}
type Labeled = { label: string; value: string; line: string; role: Role };

const DIRECTION_MARKS = /[‎‏‪-‮⁦-⁩]/g;
// Zero-width characters and the byte-order mark, which Word and copy-paste leave inside words.
const INVISIBLE = /[\u200b-\u200d\u2060\ufeff\u00ad]/g;
const BULLET = /^\s*(?:[-•*·☐]|\d{1,2}[.)])\s+/;

/** Splits the text into lines tagged with their section, and "label: value" pairs. */
function scan(text: string): { lines: Line[]; labeled: Labeled[] } {
  const lines: Line[] = [];
  const labeled: Labeled[] = [];
  let role: Role = "other";
  const raw = text.replace(DIRECTION_MARKS, "").replace(INVISIBLE, "").replace(/ /g, " ").replace(/\r\n?/g, "\n").split("\n");
  const blocks = partyBlocks(raw);
  for (let i = 0; i < raw.length; i++) {
    const line = raw[i].trim();
    if (!line || PARTY_START.test(line)) continue;
    const party = blocks.get(i);
    if (party) {
      lines.push({ text: line, role: party.role, block: party.block });
      for (const segment of line.split(SEGMENT_SEPARATOR).filter((s) => !SEGMENT_SEPARATOR.test(s))) {
        const m = LABELED.exec(segment);
        const value = m?.[4].trim();
        if (m && labelKind(m[2]) && value && !/^[—_\-–.]+$/.test(value)) labeled.push({ label: m[2].trim(), value, line, role: party.role });
      }
      continue;
    }
    // "# Title" starts the document; "## Section" (or a short line ending with ":") names what follows.
    if (/^#\s/.test(line)) {
      role = "other";
      continue;
    }
    const heading = /^#{2,6}\s+(.*)$/.exec(line)?.[1] ?? plainHeading(line);
    if (heading !== undefined) {
      role = sectionRole(heading);
      continue;
    }
    lines.push({ text: line, role });
    for (const segment of line.split(SEGMENT_SEPARATOR).filter((s) => !SEGMENT_SEPARATOR.test(s))) {
      const m = LABELED.exec(segment.replace(BULLET, ""));
      if (!m) continue;
      let value = m[4].trim();
      // A label alone on its line (common in Word tables): the value is on the next line.
      if (!value && labelKind(m[2]) && raw[i + 1]?.trim() && !LABELED.test(raw[i + 1])) value = raw[i + 1].trim();
      if (value && !/^[—_\-–.]+$/.test(value)) labeled.push({ label: m[2].trim(), value, line, role });
    }
  }
  return { lines, labeled };
}

/**
 * Israeli numbers in any local or international form → E.164 (+972521234567); numbers from other
 * countries (an owner living abroad) must be written with + or 00. Undefined when it cannot be a phone.
 */
export function normalizePhone(value: string): string | undefined {
  const trimmed = value.trim();
  const digits = trimmed.replace(/\D/g, "");
  const international = trimmed.startsWith("+") || trimmed.startsWith("00");
  const full = trimmed.startsWith("00") ? digits.slice(2) : digits;
  let local: string;
  if (international || digits.startsWith("972")) {
    if (!full.startsWith("972")) return full.length >= 8 && full.length <= 15 ? `+${full}` : undefined;
    local = full.slice(3).replace(/^0/, "");
  } else if (digits.startsWith("0")) {
    local = digits.slice(1);
  } else return undefined;
  // Mobile and 07x numbers have 9 digits after the 0; landlines (02, 03, 04, 08, 09) have 8.
  const valid = /^[57]/.test(local) ? local.length === 9 : /^[2-489]/.test(local) && local.length === 8;
  return valid ? `+972${local}` : undefined;
}

const MONTHS: Record<string, number> = {
  ינואר: 1, ינו: 1, פברואר: 2, פבר: 2, מרץ: 3, מרס: 3, אפריל: 4, אפר: 4, מאי: 5, יוני: 6, יולי: 7, אוגוסט: 8, אוג: 8,
  ספטמבר: 9, ספט: 9, אוקטובר: 10, אוק: 10, נובמבר: 11, נוב: 11, דצמבר: 12, דצמ: 12,
  january: 1, jan: 1, february: 2, feb: 2, march: 3, mar: 3, april: 4, apr: 4, may: 5, june: 6, jun: 6, july: 7, jul: 7,
  august: 8, aug: 8, september: 9, sep: 9, sept: 9, october: 10, oct: 10, november: 11, nov: 11, december: 12, dec: 12,
};

const monthOf = (word: string) => MONTHS[word.toLowerCase().replace(/['׳.]/g, "").replace(/^ב(?=[א-ת]{3})/, "")];

/** A real calendar date (no 31 February), between 1950 and 2100, as ISO. */
function isoDate(year: number, month: number, day: number): string | undefined {
  if (year < 1950 || year > 2100 || !month) return undefined;
  const d = new Date(Date.UTC(year, month - 1, day));
  if (d.getUTCFullYear() !== year || d.getUTCMonth() !== month - 1 || d.getUTCDate() !== day) return undefined;
  return d.toISOString().slice(0, 10);
}

// Dates as Israeli documents write them: day first. "2026-12-31", "31/12/2026", "31.12.26",
// "1 בינואר 2026", "1 בינו׳ 2026", "1 January 2026", "January 1, 2026".
const DATE = /\d{4}-\d{2}-\d{2}|\d{1,2}[./-]\d{1,2}[./-](?:\d{4}|\d{2})(?!\d)|\d{1,2}(?:st|nd|rd|th)?\s+(?:of\s+)?[א-תa-z]+['׳.]?,?\s+\d{4}|[a-z]+\.?\s+\d{1,2}(?:st|nd|rd|th)?,?\s+\d{4}/gi;

/** One date in any of the forms above → "2026-12-31"; undefined when it is not a real date. */
export function parseDate(value: string): string | undefined {
  const v = value.trim();
  let m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(v);
  if (m) return isoDate(Number(m[1]), Number(m[2]), Number(m[3]));
  m = /^(\d{1,2})[./-](\d{1,2})[./-](\d{2,4})$/.exec(v);
  if (m) return isoDate(m[3].length === 2 ? 2000 + Number(m[3]) : Number(m[3]), Number(m[2]), Number(m[1]));
  m = /^(\d{1,2})(?:st|nd|rd|th)?\s+(?:of\s+)?([א-תa-z]+['׳.]?),?\s+(\d{4})$/i.exec(v);
  if (m) return isoDate(Number(m[3]), monthOf(m[2]), Number(m[1]));
  m = /^([a-z]+)\.?\s+(\d{1,2})(?:st|nd|rd|th)?,?\s+(\d{4})$/i.exec(v);
  if (m) return isoDate(Number(m[3]), monthOf(m[1]), Number(m[2]));
  return undefined;
}

/** Every real date in a text, in order. */
export const findDates = (value: string) => [...value.matchAll(DATE)].flatMap((m) => parseDate(m[0]) ?? []);
/** Each date-like token in place, undefined where it is not a real date ("31/02/2026"). */
const dateTokens = (value: string) => [...value.matchAll(DATE)].map((m) => parseDate(m[0]));
const allDates = findDates;

/** "₪1,200", "1,200 ש״ח", "ILS 1200.50" → minor units. */
export function parseMoney(value: string): number | undefined {
  const m = /(\d{1,3}(?:,\d{3})+|\d+)(?:\.(\d{1,2}))?/.exec(value.replace(DIRECTION_MARKS, ""));
  if (!m) return undefined;
  return Number(m[1].replace(/,/g, "")) * 100 + Number((m[2] ?? "0").padEnd(2, "0"));
}

/** "גוש 6123 חלקה 45", "חלקה 31 בגוש 8150", "block 6123, parcel 45" → the land registry numbers. */
export function parseRegistry(text: string): { block: string; parcel: string } | undefined {
  const m =
    /גוש\s*(\d+)\s*,?\s*ו?ב?חלקה\s*(\d+)/.exec(text) ?? /block\s*(\d+)\s*,?\s*parcel\s*(\d+)/i.exec(text);
  if (m) return { block: m[1], parcel: m[2] };
  const r = /חלקה\s*(\d+)\s*,?\s*ו?ב?גוש\s*(\d+)/.exec(text) ?? /parcel\s*(\d+)\s*,?\s*(?:in\s+)?block\s*(\d+)/i.exec(text);
  return r ? { block: r[2], parcel: r[1] } : undefined;
}

/** A name without titles, quotes or "(hereinafter …)": "מר משה לוי (להלן: "הבעלים")" → "משה לוי". */
export function cleanName(value: string): string | undefined {
  const name = value
    .replace(/\((?:להלן|hereinafter)[^)]*\)?/gi, "")
    .replace(/^\s*(?:מר|גב['׳]?|הגב['׳]?|ה["״]ה|ד["״]ר|עו["״]ד|mr|mrs|ms|miss|dr)\.?\s+/i, "")
    .replace(/^["'“”„]+|["'“”„]+$/g, "")
    .replace(/[\s,;:]+$/, "")
    .replace(/\s+/g, " ")
    .trim();
  return /[א-תa-z]/i.test(name) && name.length <= 120 ? name : undefined;
}

export const EMAIL_FORMAT = /^[^\s@]+@[^\s@.]+(?:\.[^\s@.]+)*\.[a-z]{2,}$/i;

/** The first email address in a value, lower-cased and without trailing punctuation. */
export function cleanEmail(value: string): string | undefined {
  const email = value.match(EMAIL)?.[0].replace(/[.,;:]+$/, "").toLowerCase();
  return email && EMAIL_FORMAT.test(email) ? email : undefined;
}

const VAT = /מע["״]?מ|\bvat\b/i;

/**
 * A fee as agreements write it: "6% משכר הדירה", "₪620 לחודש", "8.5% + מע״מ או 400 ₪, לפי הגבוה".
 * A percentage and an amount together mean a percentage with a monthly minimum.
 */
export function parseFee(value: string): { model?: FeeModel; percent?: number; amountMinor?: number; plusVat: boolean } {
  const v = value.replace(DIRECTION_MARKS, "");
  const percentMatch = /(\d+(?:\.\d+)?)\s*%/.exec(v);
  const percent = percentMatch ? Number(percentMatch[1]) : undefined;
  const rest = percentMatch ? v.replace(percentMatch[0], " ") : v;
  const currency = /₪|ש["״]ח|\bils\b|\bnis\b|שקל|shekel/i.test(rest);
  const amountMinor = currency || percent === undefined ? parseMoney(rest) : undefined;
  const model: FeeModel | undefined =
    percent !== undefined && amountMinor !== undefined ? "percent_with_minimum" : percent !== undefined ? "percent_of_rent" : amountMinor !== undefined ? "fixed" : undefined;
  return { model, percent, amountMinor, plusVat: VAT.test(v) };
}

const QUARTERLY = /רבעון|רבעוני|quarter/i;
const MONTHLY = /כל חודש|חודשי|month/i;

const sameText = (a: string, b: string) => a.replace(/[\s"'״׳.-]/g, "").toLowerCase() === b.replace(/[\s"'״׳.-]/g, "").toLowerCase();

export function extractAgreement(text: string, own: OwnValues): AgreementExtract {
  const { lines, labeled } = scan(text);
  const isOwn = (v: string) => sameText(v, own.name) || sameText(v, own.email) || normalizePhone(v) === own.phone;
  // The owner's details: from the owner's section first, then from sections about nothing in particular.
  const partyLabeled = [...labeled.filter((l) => l.role === "owner"), ...labeled.filter((l) => l.role === "other")].filter((l) => !isOwn(l.value));
  const partyLines = lines.filter((l) => l.role === "owner" || l.role === "other");

  const byLabel = (kind: ReturnType<typeof labelKind>, parse: (v: string) => string | undefined = (v) => v): Found | undefined => {
    for (const l of partyLabeled) {
      if (labelKind(l.label) !== kind) continue;
      const value = parse(l.value);
      if (value) return { value, line: l.line, how: "label" };
    }
    return undefined;
  };
  /** The first match in the owner's lines; `near` / `notNear`: a word that must / must not come just before it. */
  const byPattern = (re: RegExp, parse: (v: string) => string | undefined = (v) => v, { near, notNear }: { near?: RegExp; notNear?: RegExp } = {}): Found | undefined => {
    for (const l of partyLines) {
      for (const m of l.text.matchAll(new RegExp(re.source, "gi"))) {
        const before = l.text.slice(Math.max(0, m.index! - 20), m.index);
        if ((near && !near.test(before)) || notNear?.test(before)) continue;
        const value = parse(m[1] ?? m[0]);
        // "—" or "______": the field was left empty in the document.
        if (value && !/^[—_\-–.\s]+$/.test(value) && !isOwn(value)) return { value: value.trim(), line: l.text, how: "pattern" };
      }
    }
    return undefined;
  };

  const ID_WORD = /ת\.?\s?ז|ח\.?\s?פ|זהות|\bID\b|company (?:no|number)|registration/i;
  const taxId = byLabel("taxId", (v) => /\d[\d-]{4,}\d/.exec(v)?.[0].replace(/-/g, "")) ?? byPattern(ID_NUMBER, (v) => v.replace(/-/g, ""), { near: ID_WORD });
  // In a party block: the first line is the name (with the ID after it), a line starting "מרח׳ / of" the address.
  const ownerBlock = lines.filter((l) => l.block !== undefined && l.role === "owner" && !DESIGNATION.test(l.text));
  const blockLine = (test: (l: Line) => boolean, parse: (l: Line) => string | undefined): Found | undefined => {
    for (const l of ownerBlock.filter(test)) {
      const value = parse(l);
      if (value) return { value, line: l.text, how: "pattern" };
    }
    return undefined;
  };
  const isLabeled = (l: Line) => Boolean(LABELED.exec(l.text) && labelKind(LABELED.exec(l.text)![2]));
  const blockName = blockLine(
    (l) => !isLabeled(l) && !ADDRESS_START.test(l.text),
    (l) => cleanName(l.text.split(/,?\s*(?:ת\.?\s?ז|ח\.?\s?פ|\bID\b|company no)/i)[0]),
  );
  const blockAddress = blockLine(
    (l) => ADDRESS_START.test(l.text),
    (l) => {
      const v = l.text.replace(ADDRESS_START, "").trim();
      return v && !/^[—_\-–.\s]+$/.test(v) ? v : undefined;
    },
  );
  const name =
    byLabel("name", cleanName) ??
    blockName ??
    byPattern(/(?:לבין|ובין)\s*:?\s*([^,\n(]{2,60}?)\s*(?=,|\(|ת\.?\s?ז|ח\.?\s?פ|$)/, cleanName) ??
    byPattern(/between\b.*?\band\s+([^,\n(]{2,60}?)\s*(?=,|\(|\bID\b)/, cleanName);
  // An ID such as 034827139 also looks like a landline number; one right after "ID" is not a phone.
  const phone = byLabel("phone", normalizePhone) ?? byPattern(PHONE_IL, normalizePhone, { notNear: ID_WORD });
  const email = byLabel("email", cleanEmail) ?? byPattern(EMAIL, cleanEmail);
  const billingAddress =
    byLabel("address") ??
    blockAddress ??
    byPattern(/(?:מרחוב|מרח['׳]|ברחוב|שכתובתו|שכתובתה|residing at|of address)\s+([^\n(]+?)(?=\s*(?:,\s*(?:טלפון|טל|נייד|phone|tel|mobile|דוא|e-?mail)|\(|$))/);

  const isCompany = /^5\d{8}$/.test(taxId?.value ?? "") || /בע["״]?מ|בעמ\b|\bltd\b|limited|\binc\b|חברה|שותפות|עמותה/i.test(name?.value ?? "");
  const kind: Found<PartyKind> = { value: isCompany ? "company" : "individual", line: (taxId ?? name)?.line ?? "", how: "pattern" };

  // The terms: labeled anywhere outside the company's own details.
  const terms: AgreementExtract["terms"] = {};
  const setFee = (fee: ReturnType<typeof parseFee>, found: <T>(value: T) => Found<T>) => {
    if (!fee.model) return;
    terms.feeModel = found(fee.model);
    if (fee.percent !== undefined) terms.feePercent = found(fee.percent);
    if (fee.amountMinor !== undefined) terms.feeMinor = found(fee.amountMinor);
    if (fee.plusVat) terms.plusVat = found(true);
  };
  for (const l of labeled.filter((x) => x.role !== "company")) {
    const label = normalizeLabel(l.label);
    const found = <T,>(value: T): Found<T> => ({ value, line: l.line, how: "label" });
    if (/סף|אישור|threshold|approval/.test(label)) {
      const amount = parseMoney(l.value);
      if (amount !== undefined) terms.approvalThresholdMinor ??= found(amount);
    } else if (/מועד החיוב|חיוב|billing|billed|payment schedule/.test(label)) {
      if (QUARTERLY.test(l.value)) terms.billingFrequency ??= found("quarterly" as const);
      else if (MONTHLY.test(l.value)) terms.billingFrequency ??= found("monthly" as const);
    } else if (/דמי ה?ניהול|תמורה|שכט|שכר טרחה|\bfee\b|management fee/.test(label)) {
      if (!terms.feeModel) setFee(parseFee(l.value), found);
    } else if (/תקופ|תוקף|\bterm\b|period/.test(label)) {
      // "start – end": positions matter, so an impossible start date is not replaced by the end date.
      const [start, end] = dateTokens(l.value);
      if (start) terms.startDate ??= found(start);
      if (end) terms.endDate ??= found(end);
    } else if (/תחיל|מיום|start|commenc|effective/.test(label)) {
      const [d] = allDates(l.value);
      if (d) terms.startDate ??= found(d);
    } else if (/סיום|עד יום|\bend\b|expir/.test(label)) {
      const [d] = allDates(l.value);
      if (d) terms.endDate ??= found(d);
    }
  }

  // Free-text agreements: "החל מיום 01/03/2026 ועד יום …", "a management fee of 6% of the rent".
  for (const l of lines.filter((x) => x.role !== "company")) {
    const found = <T,>(value: T): Found<T> => ({ value, line: l.text, how: "pattern" });
    const start = new RegExp(`(?:החל מיום|מיום|commencing on|starting on|effective from|from)\\s+(${DATE.source})`, "i").exec(l.text);
    const end = new RegExp(`(?:ועד יום|עד יום|until|through|ending on)\\s+(${DATE.source})`, "i").exec(l.text);
    if (start && parseDate(start[1])) terms.startDate ??= found(parseDate(start[1])!);
    if (end && parseDate(end[1])) terms.endDate ??= found(parseDate(end[1])!);
    // "…signed on <date>": in many agreements the term starts on signing.
    const signed = new RegExp(`(?:נערך ונחתם|ונחתם|נחתם|made and signed on|signed on|made on)\\s+(?:ביום|on)?\\s*(${DATE.source})`, "i").exec(l.text);
    if (signed && parseDate(signed[1])) terms.startDate ??= found(parseDate(signed[1])!);
    // The fee sentence; a free-text fee needs a percentage or a currency to count.
    const fee = /(?:דמי ה?ניהול|שכ["״]?ט|שכר טרחה|management fee)([^\n]*)/i.exec(l.text);
    if (fee && !terms.feeModel) {
      const parsed = parseFee(fee[1]);
      if (parsed.percent !== undefined || /₪|ש["״]ח|ils|nis|שקל/i.test(fee[1])) setFee(parsed, found);
    }
    if (!terms.billingFrequency && /(?:בתחילת|בסוף)\s+כל\s+רבעון|quarterly|each quarter/i.test(l.text)) terms.billingFrequency = found("quarterly" as const);
  }

  // Property addresses: the lines of the properties section, and "Property address:" anywhere.
  const properties: Found[] = [
    ...lines
      .filter((l) => l.role === "property")
      .flatMap((l) => {
        const m = LABELED.exec(l.text.replace(BULLET, ""));
        const kindOfLabel = m && labelKind(m[2]);
        if (m && !kindOfLabel) return []; // another labeled detail of the property ("Area: 78")
        const value = (m ? m[4] : l.text.replace(BULLET, "")).trim();
        return value && !/^[—_\-–.]+$/.test(value) ? [{ value, line: l.text, how: "label" as const }] : [];
      }),
    ...labeled
      .filter((l) => l.role !== "property" && /כתובת הנכס|property address|premises/.test(normalizeLabel(l.label)))
      .map((l) => ({ value: l.value, line: l.line, how: "label" as const })),
  ];

  // Co-owners: more than one name or ID in the owner's section. Only the first is imported.
  const ownerIds = new Set(labeled.filter((l) => l.role === "owner" && labelKind(l.label) === "taxId").map((l) => l.value.replace(/\D/g, "")));
  const ownerNames = labeled.filter((l) => l.role === "owner" && labelKind(l.label) === "name").length;

  // No properties section (most agreements): the property in the recitals, "…דירה ברחוב הרצל 12 ברמת גן, הידוע כגוש 6123 חלקה 45".
  if (!properties.length) {
    for (const l of lines.filter((x) => x.role !== "company")) {
      const registry = parseRegistry(l.text);
      const street = /(?:ברחוב|ברח['׳]|at)\s+([^()\n]+?)(?=\s*,?\s*(?:הידוע|והידוע|הידועה|known as|\(|;|$))/i.exec(l.text);
      if (!registry && !(street && /נכס|דירה|דירת|property|apartment|premises/i.test(l.text))) continue;
      const address = street?.[1].trim() && !/^[—_\-–.\s]+$/.test(street[1]) ? street[1].trim() : "";
      const value = `${address}${registry ? `${address ? " " : ""}(גוש ${registry.block}, חלקה ${registry.parcel})` : ""}`;
      if (value) properties.push({ value, line: l.text, how: "pattern" });
    }
  }

  const warnings: ExtractWarning[] = [];
  if (taxId && !isValidIsraeliId(taxId.value)) warnings.push("invalid_tax_id");
  if (ownerIds.size > 1 || ownerNames > 1) warnings.push("multiple_owners");
  if (terms.startDate && terms.endDate && terms.endDate.value <= terms.startDate.value) warnings.push("end_before_start");
  if (!name) warnings.push("no_name");
  if (!phone && !email) warnings.push("no_contact");
  if (!terms.startDate) warnings.push("no_start");

  const hebrew = (text.match(/[֐-׿]/g) ?? []).length;
  const latin = (text.match(/[a-z]/gi) ?? []).length;

  return {
    language: hebrew >= latin ? "he" : "en",
    customer: { kind, name, taxId, phone, email, billingAddress },
    terms,
    properties,
    warnings,
  };
}
